import{_ as t,o,c as a,a5 as i}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"creators are quitting youtube… why?","description":"","frontmatter":{"title":"creators are quitting youtube… why?","search":false,"sidebar":false},"headers":[],"relativePath":"en/blog/creators-are-quitting-youtube-why.md","filePath":"en/blog/creators-are-quitting-youtube-why.md"}'),n={name:"en/blog/creators-are-quitting-youtube-why.md"};function r(s,e,l,u,h,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="creators-are-quitting-youtube-why" tabindex="-1">creators are quitting youtube… why? <a class="header-anchor" href="#creators-are-quitting-youtube-why" aria-label="Permalink to &quot;creators are quitting youtube… why?&quot;">​</a></h1><p>Dan Koe · 2024-07-20 · <a href="https://thedankoe.com/blog/creators-are-quitting-youtube-why/" target="_blank" rel="noreferrer">原文</a> · <a href="/blog/creators-are-quitting-youtube-why">返回中文译文</a></p><p>A post popped up on my timeline the other day.</p><p>The guy writing it is a social media manager. He’s great at growing accounts.</p><p>Now, forgive me, because I didn’t save the post (and spent 30 minutes trying to find it which is impossible on Instagram), so these aren’t his exact words.</p><p>But in the post, he mentioned that he secretly wishes for his business to fail.</p><p>Why?</p><p>Because he and his clients feel trapped by social media.</p><ul><li>They feel like they can’t be themselves and have to fuel a fake online character.</li><li>They see content as a means to an end rather than the end of means.</li><li>He feels as if they would be better off if their businesses failed so they could finally log off social media and get back to nature.</li></ul><p>I quite liked this post, it was insightful and well written, but there’s a deeper problem here and I’ve been munching on this idea for quite a while now.</p><p>The past few months, there have been plenty of YouTubers and creators in general quitting because of the algorithm not favoring them.</p><p>Rather than setting their ego aside and just <em>getting better</em>, they feel as if the social media company should conform to their style so they can survive like they would as an employee.</p><p>The entire point of becoming a creator is do do what you want, talk about you want, and play the infinite game of taking on more challenge and improving yourself to get there.</p><p>That’s why you started.</p><p>Your mind fell in love with growth, challenge, and improvement because that’s what makes life meaningful.</p><p>But soon enough, it got boring and repetitive for you.</p><p>We all know how dangerous that is.</p><p>The solution isn’t quitting altogether under the delusion that living in the woods will solve all of your problems, because that too will get boring and repetitive after the novelty of a new lifestyle wears off.</p><p>Like people who just crashed on a deserted island, it’s chaotic for a bit, but then people identify their roles, it becomes peaceful, and out of nowhere someone decides to create a little chaos to make things interesting again.</p><p>The solution is to realign.</p><p>Social media doesn’t suck, you just follow and please the wrong people.</p><p>You don’t have to write content to please the algorithm, you just lack the skill to <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">make your interests interesting</a> enough to sustain your ideal lifestyle.</p><p>You don’t have to see content as a means to an end; you can see it as an opportunity to flex your creative muscle, as a vessel for your never-ending life’s work.</p><ul><li>Yes, your income may drop until you experiment enough to find your footing.</li><li>Yes, you will have to forget the digital ideology you programmed yourself into.</li><li>And yes, there is absolutely a way to grow, but you blame the algorithm for your inability to adapt and pivot until you find the intersection of what you love and what people want.</li></ul><p>This isn’t personal, because many people are reading this, but maybe you are better off in the perceived comfort and security of a 9-5 or living in the woods until you realize that won’t solve your problems.</p><p>In my eyes, social media isn’t just an app on your phone.</p><ul><li>It’s a portal into a land of people who share your same deep interests.</li><li>It’s the metabolism of your mind, allowing you to hunt for beautiful ideas and share them with the world. (Most of my posts are just notes or ideas I want to share).</li><li>It’s an open market where you can <a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">build a life-changing product</a> and distribute it to the like minds you attract (to make a meaningful income).</li></ul><p>Evolution doesn’t go backward.</p><p>The digital march forward will only continue faster and faster.</p><p>You can find your place, or you can quit and realize how good you had it before.</p>',30)])])}const c=t(n,[["render",r]]);export{y as __pageData,c as default};
